from h import *
R(9379335,"فطائر الأفوكادو",
"فطائر الأفوكادو هذه مليئة بالفوائد وتقدم لمسة منعشة على فطور كلاسيكي.",
"8 فطائر","حصة واحدة",
["½ حبة أفوكادو مهروسة","⅓ كوب موز مهروس، أي حوالي موزة متوسطة","1 كوب حليب الصويا أو حليب نباتي من اختيارك","120 جرامًا من دقيق القمح الكامل، أي حوالي 1 كوب","1 ملعقة كبيرة سكر قصب أو سكر جوز الهند غير المكرر","2 ملعقة صغيرة بيكنج باودر"],
["سخّن صينية القلي مسبقًا على نار متوسطة. ثم اهرس الموز والأفوكادو في وعاء خلط متوسط واسكب الحليب. اخلط جيدًا.","بعد ذلك، أضف الدقيق والسكر والبيكنج باودر. ثم قلّب حتى تمتزج دون إفراط في الخلط.","اسكب العجين بالمغرفة على صينية القلي المسخنة مسبقًا، لتصنع فطائر قطرها حوالي 4 بوصات. اطهِها لمدة 4-5 دقائق حتى تصبح الحواف ذهبية وتظهر عدة فقاعات على السطح.","ثم اقلبها وواصل الطهي حتى تنضج الفطائر تمامًا."],
["زِن الدقيق للحصول على أدق النتائج. فاغتراف الدقيق من الكيس غالبًا ما يؤدي إلى استخدام كمية زائدة منه بسبب كبسه في كوب القياس.","إذا لم يكن لديك ميزان مطبخ، فاسكب الدقيق بالملعقة في كوب القياس واكشط السطح بسكين، لكن لا تغترفه من الكيس.","استخدم بيكنج باودر طازجًا وفعّالًا. فالبيكنج باودر المفتوح الذي بقي في الخزانة عدة أشهر قد يبدأ بفقدان فعاليته.","لا حاجة إلى الإفراط في خلط عجين الفطائر. إذا وُجدت بعض الكتل الصغيرة فلا بأس بذلك إطلاقًا. فقط اخلط حتى يمتزج ولا تتبقى كتل دقيق.","سخّن المقلاة أو صينية القلي مسبقًا. يجب أن تكون ساخنة قبل سكب عجين الفطائر لمنع الالتصاق ولينضج بالتساوي.","استخدم نارًا متوسطة لطهي الفطائر. ورغم أنه يجب أن تكون المقلاة ساخنة، فهذا لا يعني استخدام نار عالية. فقد يؤدي ذلك إلى نضج غير متساوٍ، بخارج مقرمش وداخل طري.","اقلب الفطائر مرة واحدة فقط عندما تصبح الحواف ذهبية وتظهر عدة فقاعات على السطح. فالقلب المتكرر قد يجعلها تنكمش ويعطي قوامًا أكثر كثافة.","يبقى المتبقي صالحًا في الثلاجة لمدة 2-3 أيام أو يُجمَّد لمدة تصل إلى 3 أشهر."])
R(9380481,"عشاء الحمص على صينية الخبز",
"الخضار المحمّصة والحمص يشكلان مزيجًا رابحًا في وجبة العشاء الرائعة هذه على صينية واحدة.",
"4 حصص","حصة واحدة",
["1½ كوب حمص (مطبوخ أو معلب، حوالي علبة 15 أونصة)","عبوة فطر 8 أونصات (227 جرامًا) (مقطعة إلى نصفين)","1 باينت طماطم كرزية (حوالي 2 كوب)","1 رطل بطاطس صفراء صغيرة (مقطعة إلى نصفين، وأرباعًا إذا كانت أكبر)","1 حبة كوسا (مقطعة طوليًا إلى أرباع)","1 حبة فلفل رومي أحمر (مقطعة إلى قطع بحجم 1 بوصة)","¼ كوب عصير ليمون","¼ كوب مرق خضار","½ ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة مسحوق البصل","½ ملعقة صغيرة أوريجانو","½ ملعقة صغيرة إكليل الجبل مجروش","ملح + فلفل (حسب الرغبة)"],
["سخّن الفرن مسبقًا على 425° فهرنهايت (220° مئوية) بوضع التحميص بالهواء الساخن وبطّن صينية خبز كبيرة بورق الزبدة.","ضع جميع الخضار المقطعة والحمص في وعاء خلط كبير، ثم أضف جميع مكونات التتبيلة وقلّب جيدًا.","انقل كل شيء إلى الصينية في طبقة واحدة، لكن لا تسكبه دفعة واحدة من الوعاء. فأنت لا تريد كمية زائدة من التتبيلة على الصينية. حمّصه لمدة 20 دقيقة، ثم أخرج الصينية من الفرن واقلب كل شيء. ثم حمّصه لمدة 10 دقائق أخرى، أو حتى تصل إلى درجة النضج المطلوبة.","قدّمه كما هو، أو مع الأرز، أو في لفائف التورتيلا."],
[])
R(9388632,"سلطة الفلفل الرومي المحمّص",
"مدخّنة وحلوة وزاهية بشكل لا يُقاوَم، سلطة الفلفل الرومي المحمّص هذه طبق بسيط وجريء يضفي اللون والنكهة على المائدة.",
"4 حصص","حصة واحدة",
["4 حبات فلفل أحمر محمّص مقطعة شرائح رفيعة","1½ كوب حمص، أي حوالي علبة 15 أونصة","⅓ كوب بصل أحمر مقطع مكعبات","1 باينت (12 أونصة) طماطم كرزية من أصناف الإرث مقطعة إلى نصفين","2 ملعقة كبيرة أكوافابا أو زيت زيتون","¼ كوب عصير ليمون، أي حوالي ليمونة متوسطة","2 فص ثوم مفروم","2 ملعقة كبيرة ريحان مفروم طازجًا","1 ملعقة صغيرة أوريجانو مجفف","¼ ملعقة صغيرة فلاكس الفلفل الأحمر، اختياري","ملح + فلفل حسب الرغبة"],
["ضع شرائح الفلفل والحمص والبصل والطماطم الكرزية المقطعة إلى نصفين في وعاء خلط.","ثم، في وعاء صغير أو برطمان، اخلط جميع مكونات صلصة السلطة.","قلّب السلطة مع الصلصة حتى تتغطى بالتساوي، وقدّم."],
["إذا لم يكن لديك فلفل أحمر محمّص في المنزل، فاخبز أو اشوِ الفلفل الرومي الأحمر في الفرن حتى يلين وتسودّ قشرته. ثم قشّره بعد أن يبرد بما يكفي وقطّع الفلفل إلى شرائح رفيعة جدًا.","يبقى المتبقي صالحًا في الثلاجة لمدة 2-3 أيام في وعاء محكم الإغلاق."],
{"For the dressing":"للصلصة"})
R(9388968,"مافن التوت الأحمر (الراسبيري) النباتي [خالٍ من الزيت]",
"يحقق مافن التوت الأحمر النباتي هذا توازنًا مثاليًا بين الحلاوة والحموضة، ويتميز برطوبة مذهلة ونكهة لا تُقاوَم!",
"12 قطعة مافن","حصة واحدة",
["1 كوب حليب الصويا","2 ملعقة صغيرة عصير ليمون أو خل التفاح","1 ملعقة كبيرة قشر ليمون مبشور من حوالي ليمونة كبيرة","⅓ كوب صلصة التفاح غير المحلاة","270 جرامًا من دقيق الشوفان، أي حوالي 3 أكواب تُملأ بالملعقة وتُسوّى","½ كوب سكر جوز الهند غير المكرر أو سكر بني","2 ملعقة صغيرة بيكنج باودر","½ ملعقة صغيرة بيكربونات الصوديوم","1½ كوب توت أحمر (راسبيري) طازج","½ كوب سكر ناعم (سكر بودرة)","2 ملعقة صغيرة عصير ليمون"],
["سخّن الفرن مسبقًا على 375° فهرنهايت (190° مئوية) وجهّز صينية مافن تتسع لـ 12 قطعة. إذا لم تكن لديك صينية غير لاصقة، فاستخدم أكواب ورقية أو دهّن القوالب.","اخلط حليب الصويا وعصير الليمون في وعاء كبير واتركه جانبًا لمدة 5 دقائق ليتكاثف ويتخثر. (هذا يصنع لبنًا رائبًا نباتيًا.)","ثم أضف قشر الليمون وصلصة التفاح إلى وعاء الحليب المتخثر وقلّب.","بعد ذلك، أضف الدقيق والسكر والبيكنج باودر وبيكربونات الصوديوم. قلّب حتى تمتزج دون إفراط في الخلط. ثم أضف التوت الأحمر بالتحريك الرفيع من الأسفل إلى الأعلى.","وزّع العجين على قوالب المافن الاثني عشر واخبزه لمدة 20-22 دقيقة، حتى يخرج عود الأسنان المغروز في الوسط نظيفًا. أخرجه من الفرن واتركه ليبرد لمدة 20 دقيقة على الأقل قبل نقله بحذر إلى رف التبريد. المافن هش، لذا اتركه يبرد قبل نقله.","إذا كنت تستخدم الطلاء الاختياري، فاخلط السكر وعصير الليمون في وعاء صغير. وبعد أن يبرد المافن تمامًا، رشّ عليه الطلاء واتركه لبضع دقائق ليتصلب السكر، واستمتع به."],
["زِن الدقيق باستخدام ميزان المطبخ للحصول على أدق النتائج! فاغتراف الدقيق من الكيس سيكبسه، وقد يعني ذلك استخدام كمية زائدة منه مما قد ينتج عنه مافن أكثر كثافة.","استخدم بيكنج باودر طازجًا وفعّالًا. فالبيكنج باودر المفتوح في الخزانة لأكثر من 6 أشهر قد يفقد فعاليته.","اترك المافن ليبرد في صينيته لمدة 20 دقيقة على الأقل قبل نقله إلى رف التبريد. هذا المافن هش عندما يكون دافئًا، لذا امنحه وقتًا ليبرد لمنع كسره.","إذا كنت تستخدم الطلاء الاختياري، فتأكد من أن المافن بارد تمامًا أولًا وضع الطلاء عليه قبل التقديم مباشرة. فحفظ المافن المطلي في وعاء محكم الإغلاق سيجعل الطلاء يذوب.","يبقى المافن صالحًا في وعاء محكم الإغلاق في درجة حرارة الغرفة لمدة 2-3 أيام، وفي الثلاجة لمدة تصل إلى أسبوع أو مجمدًا لمدة تصل إلى 3 أشهر. مستوحى من مافن الليمون والتوت الأزرق الخاص بي."],
{"Optional Glaze":"طلاء اختياري"})
R(9389046,"شوربة الشمندر المحمّص بالشبت [خالية من الزيت]",
"شوربة الشمندر المحمّص جميلة وجذابة بلونها الأحمر الزاهي الرائع. حلوة بشكل طبيعي مع لمسة حموضة من الليمون والشبت. كريمية بإتقان ولذيذة ومشبعة.",
"4 حصص","حصة واحدة",
["1½ رطل شمندر، أي حوالي 8-10 حبات صغيرة/متوسطة","1 ملعقة كبيرة زبدة نباتية، احذفها وقلّب في الماء أو المرق لوصفة خالية من الزيت","1 حبة بصل أصفر مقطعة مكعبات","1 حبة جزر كبيرة مقشّرة + مقطعة مكعبات","1 عود كرفس مقطع مكعبات","2½ كوب مرق خضار قليل الصوديوم","3 ملاعق كبيرة شبت طازج أو 2 ملعقة صغيرة شبت جاف","½ ملعقة صغيرة ملح البحر","3 ملاعق كبيرة عصير ليمون، أي حوالي ليمونة متوسطة","كريمة الكاجو","مزيد من الشبت الطازج"],
["سخّن الفرن مسبقًا على 425° فهرنهايت (220° مئوية) بوضع التحميص بالهواء الساخن. إذا لم يكن لديك فرن بالهواء الساخن أو وظيفة التحميص، فاستخدم وضع الخَبز فقط، مع إتاحة وقت أطول قليلًا ليلين الشمندر.","افرك الشمندر واغسله واقطع أطرافه. إذا كان الشمندر كبيرًا، فقطّعه إلى نصفين لينضج أسرع، وإلا فاتركه كاملًا. باستخدام ورق الألمنيوم، اصنع جيوبًا تحتوي الشمندر بداخلها، وضع الجيوب على صينية خبز. اطوِ جوانب الورق لمنع انتشار صبغة الشمندر الحمراء وتسببها في فوضى. (ارجع إلى صور خطوات التحضير أعلاه إن لزم الأمر.) رشّ الشمندر بالملح والفلفل وحمّصه حتى يلين عند غرزه بالشوكة. سيستغرق ذلك ما بين 30-60 دقيقة بحسب مدى طزاجته (الشمندر الأطزج ينضج أسرع) وحجمه.","بينما يُحمَّص الشمندر، ذوّب الزبدة (إن استخدمتها) في مقلاة وأضف البصل والجزر والكرفس المفروم. قلّب حتى تلين، حوالي 5-7 دقائق. ثم ضعها جانبًا.","أخرج الشمندر من الفرن واتركه ليبرد قليلًا، بما يكفي للتعامل معه فقط. ثم قشّر الشمندر (ستنزع القشرة بسهولة بعد التحميص) وضعه في الخلاط. أضف الخضار المقلية وجميع المكونات المتبقية إلى الخلاط واخلطها حتى تصبح ناعمة. اعمل على دفعات إذا لزم الأمر.","قدّمها مع كريمة الكاجو ومزيد من الشبت الطازج إن رغبت. بالهناء والعافية!"],
["لتوفير الوقت، حمّص الشمندر وقشّره قبل 1-2 يوم. ثم عندما تريد تحضير الشوربة، قلّب الخضار الأخرى واخلط.","اترك قشر الشمندر عليه أثناء التحميص. فهو أسهل في التقشير بعد التحميص. (ارتدِ قفازات أثناء التقشير لتجنب احمرار أصابعك.)","لوصفة خالية من الزيت، ببساطة احذف الزبدة النباتية وقلّب في الماء أو المرق بدلًا منها.","يبقى المتبقي صالحًا في الثلاجة لمدة تصل إلى 4 أيام أو يُجمَّد في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر."],
{"Optional Garnishes":"للتزيين (اختياري)"})
R(9389346,"يخنة فطيرة الخضار في القدر البطيء",
"نسخة أقل سعرات حرارية وأقل كربوهيدرات من فطيرة الخضار المفضلة لديك. تقدم هذه اليخنة النكهات الرائعة نفسها ولكن بنسخة خالية من الغلوتين في القدر البطيء.",
"6 حصص","حصة واحدة",
["1 حبة بصل أصفر مفرومة ناعمًا","6 حبات جزر مقشّرة ومقطعة مكعبات","2 رطل بطاطس صفراء مقشّرة ومقطعة إلى مكعبات بحجم نصف بوصة","1 كوب ذرة مجمدة","1 كوب بازلاء مجمدة","4 أكواب مرق خضار قليل الصوديوم","½ ملعقة صغيرة ملح البحر أو حسب الرغبة","1 ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة مريمية مجففة","½ ملعقة صغيرة زعتر مجفف","4 ملاعق كبيرة ماء","4 ملاعق كبيرة نشا الذرة","½ كوب حليب الكاجو غير المحلى أو حليب من اختيارك"],
["ضع جميع المكونات ما عدا الماء ونشا الذرة والحليب في القدر البطيء. اطهِها على الوضع المنخفض لمدة 8 ساعات.","حوّل القدر البطيء إلى الوضع العالي. ثم في وعاء صغير أو برطمان، اخلط الماء ونشا الذرة جيدًا. أضف هذا الخليط إلى القدر البطيء واطهِ على الوضع العالي لمدة 30 دقيقة. سيؤدي ذلك إلى تكثيف اليخنة.","أطفئ القدر البطيء وأضف الحليب وقلّب وقدّم.","ضع جميع المكونات ما عدا الماء ونشا الذرة والحليب في القدر، واطهِها بالضغط على ضغط عالٍ لمدة 6 دقائق.","في هذه الأثناء، اخفق الماء ونشا الذرة في وعاء صغير وضعه جانبًا.","عند انتهاء المؤقت، أطلق البخار بسرعة من الصمام وافتح الغطاء عندما يكون ذلك آمنًا. حوّل القدر إلى وظيفة التقليب (Sauté) واسكب خليط نشا الذرة في القدر وقلّب لمدة 5 دقائق مع التحريك المستمر. ثم أطفئ القدر وأضف الحليب وقلّب واستمتع بها."],
["نشا الذرة ضروري لتكثيف المرق. إذا لم تستطع تناول نشا الذرة، فيمكنك استبداله بالدقيق متعدد الاستخدامات أو دقيق الأرز البني بضعف الكمية. (أي 8 ملاعق كبيرة من الدقيق مع الماء لخليط التكثيف.) تختلف القدور البطيئة اختلافًا كبيرًا، لذا إذا وجدت أن الخضار لا تلين بما يكفي بعد الطهي عدة ساعات على الوضع المنخفض، فحوّل الجهاز إلى الوضع العالي لبقية وقت الطهي. لإضافة البروتين، أضف فاصولياء كلوية بيضاء معلبة أو عدسًا نحو نهاية الطهي. أو يمكنك استخدام التوفو الحريري المخلوط بدلًا من الحليب. ولجعل هذا الطبق أغنى (رغم أن ذلك سيزيد محتوى الدهون)، استخدم حليب جوز الهند المعلب (الخفيف لتقليل الدهون) بدلًا من حليب الكاجو في نهاية الطهي. يبقى المتبقي صالحًا في الثلاجة لمدة تصل إلى 4 أيام، أو يُجمَّد لمدة تصل إلى 3 أشهر. يمكنك استبدال البطاطس بالبطاطا الحلوة، أو عمل مزيج بالنصف، إن أردت."],
{"Slow Cooker Instructions":"طريقة التحضير في القدر البطيء","Instant Pot Instructions":"طريقة التحضير في Instant Pot"})
R(9390900,"قرنبيط حلو وحامض نباتي",
"هذا القرنبيط الحلو والحامض النباتي حلو ولزج ولذيذ بشكل لا يصدق!",
"4 حصص","حصة واحدة",
["4 أكواب زهيرات قرنبيط، أي حوالي رأس صغير مقطع إلى قطع بحجم اللقمة","½ كوب دقيق الأرز البني","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة مسحوق البصل","½ ملعقة صغيرة ملح البحر، اختياري","½ كوب ماء","½ كوب شراب القيقب","¼ كوب خل الأرز","¼ كوب تاماري قليل الصوديوم أو صلصة الصويا إن لم تكن تتجنب الغلوتين","¼ كوب كاتشب","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة كبيرة دقيق الأرز البني، اختياري لتكثيف الصلصة","1 حبة فلفل رومي أحمر مقطعة شرائح","1 كوب أناناس مقطع مكعبات","أرز بني أو كينوا","بصل أخضر","سمسم"],
["سخّن الفرن مسبقًا على 425 درجة فهرنهايت (220 درجة مئوية) وبطّن صينية خبز بورق الزبدة.","قطّع القرنبيط إلى قطع صغيرة بحجم اللقمة وضعه جانبًا. ثم ضع بقية مكونات القرنبيط في وعاء خلط متوسط واخفقها حتى تمتزج لتصنع الخليط. ضع قطع القرنبيط المقطعة في الخليط وقلّب جيدًا لتتغطى القطع بالتساوي.","رتّب القرنبيط المغطى على صينية الخبز في طبقة واحدة، لكن لا تسكب كل شيء دفعة واحدة من الوعاء. فأنت لا تريد خليطًا زائدًا على الصينية وإلا قد تلتصق القطع ببعضها وتمنع القرمشة.","اخبزه لمدة 20-25 دقيقة، مع قلبه مرة واحدة عند منتصف المدة حتى تصل إلى درجة القرمشة المطلوبة.","بينما يُخبز القرنبيط، حضّر الصلصة الحلوة والحامضة. اخفق جميع مكونات الصلصة (ما عدا الفلفل والأناناس) في وعاء صغير أو كوب قياس وضعها جانبًا.","ثم قلّب الفلفل الأحمر وقطع الأناناس في مقلاة كبيرة مع ملعقة كبيرة من الماء أو المرق لمنع الالتصاق. افعل ذلك على نار متوسطة إلى عالية حتى يتحمّر قليلًا. ثم اخفض الحرارة إلى متوسطة إلى منخفضة واسكب الصلصة في المقلاة ودعها تغلي على نار هادئة حتى تتكاثف قليلًا، حوالي 5 دقائق.","بحلول ذلك الوقت، يجب أن يكون القرنبيط جاهزًا. أضفه إلى المقلاة مع الصلصة وقلّب برفق لتتغطى كل قطعة بالتساوي.","قدّمه فوق الأرز أو الكينوا وزيّنه بالسمسم والبصل الأخضر."],
["لا تسكب القرنبيط على صينية الخبز بعد تغطيته بالخليط. فأنت لا تريد أي خليط زائد على الصينية، وإلا فسيلتصق بها وقد تلتصق القطع ببعضها مما يقلل من قرمشة طبقتها الخارجية. خصص وقتًا لوضع القرنبيط المغطى بالخليط في طبقة واحدة، قطعة تلو الأخرى، مع ترك مسافة كبيرة بينها للحصول على أفضل النتائج. طعمه أفضل وهو طازج، لكن يبقى المتبقي صالحًا في الثلاجة في وعاء محكم الإغلاق لمدة 3-4 أيام."],
{"For the cauliflower":"للقرنبيط","For the vegan sweet and sour sauce":"للصلصة النباتية الحلوة والحامضة","For Serving":"للتقديم"})
R(9391250,"سلطة الحمص والأفوكادو",
"سلطة حمص وأفوكادو منعشة وزاهية، غنية بالنكهة ومشبعة بشكل مدهش! تجهز في 15 دقيقة فقط.",
"3 حصص","حصة واحدة",
["1½ كوب حمص مطبوخ أو معلب (حوالي علبة 15 أونصة)","1 حبة أفوكادو متوسطة مقطعة مكعبات","1 حبة طماطم متوسطة مقطعة إلى قطع بحجم اللقمة","¼ كوب بصل أحمر مقطع مكعبات","2-3 ملاعق كبيرة ريحان طازج مفروم ناعمًا، اختياري","1 ملعقة صغيرة أوريجانو مجفف","½ ملعقة صغيرة ملح البحر أو حسب الرغبة","¼ ملعقة صغيرة مسحوق الثوم","2 ملعقة كبيرة أكوافابا"],
["إذا كنت تستخدم حمصًا معلبًا، فصفِّه لكن احتفظ بملعقتين كبيرتين من الأكوافابا (سائل الحمص). وإذا كنت تستخدم حمصًا مطبوخًا، فاحتفظ بسائل الطهي.","قطّع المكونات وضعها في وعاء متوسط. بالنسبة للأفوكادو، قطّعه إلى نصفين وانزع النواة واستخدم سكينًا لتقطيع اللب إلى مربعات داخل القشرة نفسها. ثم اغرفه بملعقة إلى وعائك.","قلّب برفق لدمج النكهات وتوزيعها بالتساوي. استمتع بها فورًا."],
["إذا كنت تستخدم حمصًا معلبًا، فاستخدم نوعًا خاليًا من الملح، أو قلّل الملح المطلوب في الوصفة وعدّله حسب الذوق. وإذا كنت تستخدم حمصًا مطبوخًا، فاحتفظ بسائل الطهي لهذه السلطة ولوجبات مستقبلية. أطهو الحمص بدون ملح وأجمّد الأكوافابا/سائل الطهي في صواني مكعبات الثلج لاستخدامه لاحقًا. وبعد التجميد، انقل مكعبات الأكوافابا إلى وعاء أو كيس بسحّاب وأبقِها مجمدة حتى الحاجة. طعم هذه السلطة أفضل في اليوم نفسه الذي تُحضَّر فيه. وإذا كنت تخطط لتحضيرها قبل التقديم، فاعصر عصير الليمون على الأفوكادو لمنعه من التحول إلى اللون البني."])
